#define BD_VK_2                   0x0003
#define BD_VK_3                   0x0004
#define BD_VK_4                   0x0005
#define BD_VK_5                   0x0006
#define BD_VK_6                   0x0007
#define BD_VK_7                   0x0008
#define BD_VK_8                   0x0009
#define BD_VK_9                   0x000a
